psql -qX -d vp_kuerbiswaechter <<'EOF'
with recursive kante as (
  select dep.relname as sicht, src.relname as quelle, src.relkind
  from pg_depend d join pg_rewrite r on r.oid=d.objid
  join pg_class dep on dep.oid=r.ev_class join pg_class src on src.oid=d.refobjid
  join pg_namespace n on n.oid=src.relnamespace
  where d.refclassid='pg_class'::regclass and n.nspname='public' and src.oid<>dep.oid),
zu as (
  select c.relname::name as sicht from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relkind='m' and c.relname like 'erg\_%'
  union select k.quelle from kante k join zu on zu.sicht=k.sicht)
select distinct k.quelle from kante k join zu on zu.sicht=k.sicht where k.relkind='r'
  and k.quelle not in (select c.relname from pg_trigger t join pg_class c on c.oid=t.tgrelid
    join pg_proc p on p.oid=t.tgfoid where p.proname='auswertung_veraltet' and not t.tgisinternal)
order by 1;
EOF

